(()=>{var g=[[1,0],[0,1],[1,1],[1,-1]],u=Object.freeze({temperature:2.2,hp:1,maxM:.22,maxMCap:10,threat:.12,threatCap:3,center:.008,plant:.08,danger:.6,nukeDanger:.4,tieRegret:.02,dubiousRegret:.06,mistakeRegret:.14,brilliantGain:.07,goodGain:.035}),E=(f,t,a)=>Math.min(a,Math.max(t,f)),d=class{static empty_grid(){return new Uint8Array(81)}static empty_plants(){return new Uint8Array(81)}static run(t,a,l,s,e,c){let o=0,r=a+s,n=l+e;for(;r>=0&&r<9&&n>=0&&n<9&&t[n*9+r]===c;)o++,r+=s,n+=e;return o}static ascend_size(t,a,l,s){let e=0;for(let c=0;c<g.length;c++){let o=g[c][0],r=g[c][1],n=1+this.run(t,a,l,o,r,s)+this.run(t,a,l,-o,-r,s);n>=4&&(e+=n)}return e}static stats(t,a){let l={1:{maxM:0,points:0,center:0,plant:0},2:{maxM:0,points:0,center:0,plant:0}};for(let s=0;s<81;s++){let e=t[s],c=s%9,o=Math.floor(s/9);if(e===1||e===2){l[e].center+=4-Math.abs(c-4)-Math.abs(o-4);continue}let r=this.ascend_size(t,c,o,1);if(r>=4){let i=l[1];i.points++,r>i.maxM&&(i.maxM=r),a&&(i.plant+=a[s])}let n=this.ascend_size(t,c,o,2);if(n>=4){let i=l[2];i.points++,n>i.maxM&&(i.maxM=n),a&&(i.plant+=a[s])}}return l}static evaluate_grid(t,a,l,s){if(s===0)return 1;if(s===1)return 0;let e=Math.max(0,Number(l[0])||0),c=Math.max(0,Number(l[1])||0),o=this.stats(t,a),r=o[1],n=o[2],i=(e-c)*u.hp;i+=(Math.min(r.maxM,u.maxMCap)-Math.min(n.maxM,u.maxMCap))*u.maxM,i+=(Math.min(r.points,u.threatCap)-Math.min(n.points,u.threatCap))*u.threat,i+=(r.center-n.center)*u.center,i+=(r.plant-n.plant)*u.plant,e>0&&n.maxM>=e&&(i-=u.danger,n.maxM>=7&&(i-=u.nukeDanger)),c>0&&r.maxM>=c&&(i+=u.danger,r.maxM>=7&&(i+=u.nukeDanger));let h=1/(1+Math.exp(-i/u.temperature));return E(h,.01,.99)}static evaluate_frame(t){return this.evaluate_grid(t.grid,t.plants,t.hp,t.winner)}static best_moves(t,a,l,s=3,e=null){let c=a===0?1:2,o=[];for(let n=0;n<81;n++){if(t.grid[n]!==0)continue;let i=n%9,h=Math.floor(n/9);if(e&&e[0]===i&&e[1]===h)continue;let p=Uint8Array.from(t.grid);p[n]=c;let m=this.evaluate_grid(p,t.plants,l,null);o.push({x:i,y:h,rate:m,view:a===0?m:1-m})}o.sort((n,i)=>i.view-n.view);let r=Math.max(1,Math.min(3,Number(s)||1));return o.slice(0,r)}static best_alternative(t,a,l){let s=this.best_moves(t,a,l,1);return s.length?s[0].view:.5}static classify(t,a){return a>=u.mistakeRegret?"blunder":a>=u.dubiousRegret?"mistake":a>=u.tieRegret?"dubious":t>=u.brilliantGain?"brilliant":t>=u.goodGain?"good":"interesting"}static analyze(t){let a=t.map(e=>this.evaluate_frame(e)),l=[],s={brilliant:0,good:0,interesting:0,dubious:0,mistake:0,blunder:0};for(let e=0;e<t.length;e++){let c=t[e],o=c.turn===1?0:1,r=e>0?t[e-1]:{grid:this.empty_grid(),plants:this.empty_plants(),hp:c.hp},n=e>0?a[e-1]:.5,i=o===0?n:1-n,h=o===0?a[e]:1-a[e],p=this.best_alternative(r,o,r.hp||c.hp),m=h-i,b=Math.max(0,p-h),M=c.winner,x=M!=null&&M===o?"brilliant":this.classify(m,b);s[x]++,l.push({index:e,mover:o,delta:m,regret:b,label:x})}return{rates:a,moves:l,counts:s}}};})();
